{
  "probability": 0.98,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "Anchor the forecast to the IOM Missing Migrants Project’s central Mediterranean death tallies and the 2024–2025 baseline.",
    "Update upward on pace observed in early 2026 (about 606 deaths by February) suggesting a high chance of 1,000+ fatalities by April.",
    "Seasonal patterns and the 2025 baseline support a continued high fatality environment into spring, increasing likelihood of crossing 1,000 before May.",
    "Calibration notes acknowledge data gaps and potential SAR improvements that could temper or accelerate the trajectory."
  ],
  "confidence": "high",
  "narrative": "Starting from the central Mediterranean reference class, the unusually high early-2026 pace combined with a robust annual baseline makes reaching 1,000 deaths by late April plausible. After applying multiple upward updates and accounting for uncertainty in reporting and SAR capacity, the calibrated posterior is 0.98 with a narrow uncertainty range.",
  "justification": {
    "anchor": {
      "probability": 0.75,
      "basis": "Reference class anchored to IOM Missing Migrants Project central Mediterranean fatalities; historical baselines (~2,000–2,500 per year; 2025 ~2,185) provide a strong starting point and align with observed early-2026 pace (606 by February)."
    },
    "factor_updates": [
      {
        "factor": "Pace of Mediterranean fatalities in early 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "With around 606 deaths by February 2026, a persistence of this pace into March–April substantially raises the probability of surpassing 1,000 before May."
      },
      {
        "factor": "Historical baseline and 2025 pace",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Annual tolls near 2,000–2,500 (2025 ~2,185) suggest that a sustained high rate in early 2026 would likely push total above 1,000 within the target window."
      },
      {
        "factor": "Weather conditions and SAR capacity",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Severe weather and SAR challenges commonly elevate fatalities, reinforcing the upward trajectory unless mitigated by operations."
      },
      {
        "factor": "Reporting lag and data uncertainty",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Early tallies often understate final totals; revisions could further lift the historic count."
      },
      {
        "factor": "Search-and-rescue capacity improvements",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Potential SAR enhancements could reduce fatalities if capacities increase, but the magnitude and timing of such changes are uncertain."
      }
    ],
    "synthesis_rationale": "Starting from a plausible anchor around 0.75, multiple upward pressures (pace, baseline, and weather/SAR risk) accumulate, tempered modestly by the possibility of SAR improvements. The combination yields a high-calibration posterior near 0.98, with a narrow range reflecting data uncertainty and potential correlations among factors."
  }
}

