{
  "probability": 0.70,
  "range_low": 0.60,
  "range_high": 0.80,
  "summary": [
    "Early-2026 pace (~606 deaths by February) makes reaching 1,000 deaths before May 2026 plausible if the pace persists into March–April.",
    "Historical base-rate around 2,000–2,500 deaths per year supports a meaningful chance, though the 1,000-frontier by May is not guaranteed.",
    "Seasonality and spring crossing patterns tend to elevate risk, reinforcing upward pressure on the probability.",
    "Uncertainty from reporting lags, weather shocks, and SAR capacity means outcomes could swing; overall, the forecast tilts toward hitting the threshold but with notable caveats."
  ],
  "confidence": "high",
  "narrative": "The combination of an unusually high start to 2026, historical seasonality, and the sustained risk environment makes surpassing 1,000 deaths by end-April 2026 plausible. While not certain due to data gaps and policy/SAR dynamics, the balance of factors supports a probability above neutral."
  ,
  "justification": {
    "anchor": {
      "probability": 0.50,
      "basis": "Reference class: IOM Missing Migrants Project Central Mediterranean fatalities; historical annual tolls around 2,000–2,500. A four-month window would on average yield ~650 fatalities, so achieving 1,000 requires an above-average pace; anchor start at 0.50 to reflect initial neutral posture before factor updates."
    },
    "factor_updates": [
      {
        "factor": "Pace of Mediterranean fatalities in early 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths by February; if this pace persists through March–April, 1,000+ by end-April becomes plausible."
      },
      {
        "factor": "Seasonality and spring crossing patterns",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Historical patterns show elevated crossing activity in spring, supporting higher fatality risk in the target window."
      },
      {
        "factor": "Weather conditions and SAR capacity",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Severe weather and SAR challenges increase risk and could raise fatalities, pushing totals higher."
      },
      {
        "factor": "Reporting lag and data uncertainty",
        "direction": "up",
        "magniture": "weak",
        "rationale": "Tallies are often revised upward; early counts may understate eventual total, contributing to upside risk."
      },
      {
        "factor": "SAR capacity/policy environment",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Improved SAR operations or policy changes could reduce deaths, tempering the upward trajectory."
      }
    ],
    "synthesis_rationale": "Starting from a neutral anchor, multiple sectoral updates predominantly push probability upward (pace, seasonality, weather, data unreliability). A single moderate downward factor (SAR capacity/policy) partially offsets but does not fully counteract the upward tilt. The result is a calibration that the 1,000-death threshold by May 1, 2026 is plausible and more likely than not, yet contingent on weather, SAR outcomes, and reporting revisions."
  }
}
